fn session_directory(
    requested: Option<&std::path::Path>,
) -> Result<std::path::PathBuf, ControlError> {
    let cwd = match requested {
        Some(path) => path.to_path_buf(),
        None => std::env::current_dir()
            .map_err(|error| failed(format!("cannot read the working directory: {error}")))?,
    };
    if !cwd.is_dir() {
        if is_foreign_filesystem_path(&cwd) {
            // Not a directory *from here* is not evidence it is wrong: T18
            // found that `--command` can start the agent inside WSL (`wsl.exe
            // -d <distro> -- ...`), where a POSIX-rooted cwd like this one is
            // exactly right and this process — running on Windows — has no
            // filesystem to check it against. Passed through unverified, on
            // the caller's word, the same trust `--cwd` already extends by not
            // defaulting it.
            return Ok(cwd);
        }
        return Err(invalid(format!(
            "--cwd is not a directory: {}",
            cwd.display()
        )));
    }
    cwd.canonicalize()
        .map_err(|error| invalid(format!("cannot resolve --cwd: {error}")))
}

/// Whether `path` looking unresolvable from here might just mean it belongs to
/// a different machine's filesystem than this process's own.
///
/// A POSIX-rooted path (`/…`) that this process's own `Path::is_absolute()`
/// does not recognise as absolute is exactly what a Windows process sees when
/// handed a WSL cwd. On a POSIX host the same string *is* absolute, so this
/// never fires there and the strict local check above still runs — the
/// distinction is load-bearing, not incidental: it is what keeps an ordinary
/// missing-directory typo refused on the platform where this process really
/// can check.
fn is_foreign_filesystem_path(path: &std::path::Path) -> bool {
    path.to_str().is_some_and(|text| text.starts_with('/')) && !path.is_absolute()
}

/// On the platform where this test actually runs (POSIX), a `/`-rooted path
/// is real and absolute, so `is_foreign_filesystem_path` must say no and the
/// strict local check above it must still refuse a path that is genuinely
/// missing. The Windows-only branch (a POSIX path this process cannot see) is
/// structurally untestable here — `Path::is_absolute()` for a `/`-rooted path
/// is `true` on this host by construction — and is verified by running the
/// Windows build against a `wsl.exe`-routed `--command` instead (T18).
#[test]
fn a_posix_rooted_path_is_not_treated_as_foreign_on_a_posix_host() {
    assert!(!is_foreign_filesystem_path(std::path::Path::new(
        "/definitely/not/a/real/directory"
    )));
}

#[test]
fn a_missing_posix_rooted_directory_is_still_refused_on_a_posix_host() {
    let error = session_directory(Some(std::path::Path::new(
        "/warpctrl-acp-no-such-directory-here",
    )))
    .expect_err("a missing directory should be refused, not passed through");

    assert_eq!(error.code, ErrorCode::InvalidParams);
}

